
package miniantivirus;

import java.util.Date;

/**
 * Represents a report generated by the antivirus application.
 * Stores the report date and the number of detected threats.
 */
public class Report {

    // Stores the date associated with the antivirus report
    public Date date;

    // Stores the number of threats detected during the scan
    public int threats;

    // Generates a report using the current report information
    public Report generate() {

        // Set the report date to the current date and time
        this.date = new Date();

        // Return the current Report object
        return this;
    }
}